use filmcraft_render::{image::Image,blend::{Blend,composite_at}};use serde_json::json;
fn image(w:usize,h:usize,variant:usize,side:usize)->Image{let mut image=Image::new(w,h);let values=[0.,0.003,0.04,0.25,0.5,0.75,1.];for (i,p)in image.px.chunks_exact_mut(4).enumerate(){let alpha=[0.,0.25,0.7,1.][(i+variant+side)%4];for c in 0..3{p[c]=values[(i*3+c+variant*5+side)%values.len()]*alpha;}p[3]=alpha;}image}
fn wire(image:&Image)->serde_json::Value{json!({"w":image.w,"h":image.h,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()})}
fn main(){let catalog:serde_json::Value=serde_json::from_slice(&std::fs::read(std::env::args().nth(1).unwrap()).unwrap()).unwrap();let mut cases=vec![];let base=image(8,4,0,0);let a=image(8,4,1,0);let b=image(8,4,2,1);
for entry in catalog.as_array().unwrap().iter().filter(|e|e["definition"]["kind"]=="VideoTransition"){let baseline:filmcraft_project::EffectInstance=serde_json::from_value(entry["instance"].clone()).unwrap();for profile in 0..3{let mut effect=baseline.clone();let definition=effect.def().unwrap();for pd in &definition.params{let param=effect.params.get_mut(pd.id).unwrap();let mut lo=param.value.clone();let mut hi=param.value.clone();match &pd.kind{
 filmcraft_project::ParamKind::Float{min,max,..}=>{let v=param.value.as_f64().unwrap_or(0.);lo=filmcraft_project::ParamValue::Float((v*0.5).clamp(*min,*max));hi=filmcraft_project::ParamValue::Float((v*1.5+0.25).clamp(*min,*max));},
 filmcraft_project::ParamKind::Angle=>{lo=filmcraft_project::ParamValue::Float(-37.);hi=filmcraft_project::ParamValue::Float(71.);},
 filmcraft_project::ParamKind::Bool=>{lo=filmcraft_project::ParamValue::Bool(false);hi=filmcraft_project::ParamValue::Bool(true);},
 filmcraft_project::ParamKind::Choice(options)=>{lo=filmcraft_project::ParamValue::Choice(0);hi=filmcraft_project::ParamValue::Choice((options.len()-1)as u32);},
 filmcraft_project::ParamKind::Color=>{lo=filmcraft_project::ParamValue::Color([0.1,0.2,0.3,1.]);hi=filmcraft_project::ParamValue::Color([0.9,0.8,0.7,1.]);},
 _=>{},
 }let times=match profile{0=>(-254016000000,254016000000),1=>(254016000000,508032000000),_=>(-508032000000,-254016000000)};param.keyframes=vec![filmcraft_project::Keyframe::new(filmcraft_time::Tick(times.0),lo),filmcraft_project::Keyframe::new(filmcraft_time::Tick(times.1),hi)];}
 let numeric:std::collections::BTreeMap<_,_>=effect.params.keys().map(|id|(id,effect.f64_at(id,filmcraft_time::Tick::ZERO).to_bits())).collect();for progress in [0.,0.37,1.]{for reverse in [false,true]{let mut la=a.clone();let mut lb=b.clone();for v in &mut la.px{*v*=0.37}for v in &mut lb.px{*v*=0.73}let mixed=if reverse{filmcraft_render::transitions::apply_scaled(&effect,&lb,&la,1.-progress,1.)}else{filmcraft_render::transitions::apply_scaled(&effect,&la,&lb,progress,1.)};let mut out=base.clone();composite_at(&mut out,&mixed,0,0,1.,Blend::Normal);cases.push(json!({"kind":"transition","effect":effect,"numericBits":numeric,"profile":profile,"progress":progress,"reverse":reverse,"bits":wire(&out)["bits"]}));}}}}
println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","base":wire(&base)["bits"],"a":wire(&a)["bits"],"b":wire(&b)["bits"],"cases":cases}));}
